import { writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const rootDir = join(__dirname, "..");
const siteUrl = "https://hellnightberlin.github.io/website/";
const lastmod = (process.env.SITEMAP_LASTMOD || new Date().toISOString()).slice(0, 10);

function sitemapXml() {
  return `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by scripts/generate-seo.mjs. Do not edit by hand. -->
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url>
    <loc>${siteUrl}</loc>
    <lastmod>${lastmod}</lastmod>
    <changefreq>weekly</changefreq>
    <priority>1.0</priority>
  </url>
</urlset>
`;
}

function robotsTxt() {
  return `# Generated by scripts/generate-seo.mjs. Do not edit by hand.
User-agent: *
Allow: /

Sitemap: ${new URL("sitemap.xml", siteUrl).toString()}
`;
}

await writeFile(join(rootDir, "sitemap.xml"), sitemapXml());
await writeFile(join(rootDir, "robots.txt"), robotsTxt());
